graphql.query:
query IntrospectionQuery {
  __schema {
    queryType { name }
    mutationType { name }
    types {
      name
      kind
      fields {
        name
        type { name kind }
      }
    }
  }
}

mutation Signup($email: String!) {
  signup(email: $email) {
    user {
      id
      email
      username
    }
    apiKey
  }
}

mutation ConnectGitHub($userId: String!, $githubId: String!, $githubToken: String!) {
  connectGitHub(userId: $userId, githubId: $githubId, githubToken: $githubToken) {
    id
    email
    githubId
  }
}

mutation RegenerateApiKey($userId: String!) {
  regenerateApiKey(userId: $userId) {
    user {
      id
      email
    }
    apiKey
  }
}

mutation RevokeApiKey($userId: String!) {
  revokeApiKey(userId: $userId) {
    id
    email
  }
}

mutation GitHubOAuth($userId: String!, $code: String!) {
  githubOAuth(userId: $userId, code: $code) {
    id
    email
    githubId
  }
}

query Ping {
  ping
}

query FilteredProjects($filter: ProjectFilterInput) {
  filteredProjects(filter: $filter) {
    id
    name
    language
    stars
    isPrivate
  }
}

query EnhancedProjects($filter: EnhancedProjectFilterInput, $sort: ProjectSortInput, $pagination: PaginationInput) {
  enhancedProjects(filter: $filter, sort: $sort, pagination: $pagination) {
    edges {
      node {
        id
        name
        language
        stars
      }
      cursor
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    totalCount
  }
}

query SearchProjects($query: String!, $filter: EnhancedProjectFilterInput, $pagination: PaginationInput) {
  searchProjects(query: $query, filter: $filter, pagination: $pagination) {
    id
    name
    description
    language
    stars
  }
}

query ProjectStatistics($filter: EnhancedProjectFilterInput) {
  projectStatistics(filter: $filter) {
    totalProjects
    totalStars
    totalForks
    languageDistribution {
      language
      count
      percentage
    }
  }
}

query TrendingProjects($timeframe: String, $limit: Int) {
  trendingProjects(timeframe: $timeframe, limit: $limit) {
    id
    name
    stars
    forks
    language
  }
}

query FeaturedProjects($limit: Int) {
  featuredProjects(limit: $limit) {
