query AuditLogs($limit: Int, $offset: Int, $actions: [AuditAction!], $resources: [AuditResource!]) {
  auditLogs(limit: $limit, offset: $offset, actions: $actions, resources: $resources) {
    edges {
      node {
        id
        action
        resource
        resourceId
        userId
        details
        ipAddress
        userAgent
        createdAt
      }
    }
    totalCount
    pageInfo {
      hasNextPage
      hasPreviousPage
    }
  }
}

query UserAuditLogs($userId: String, $limit: Int, $offset: Int) {
  userAuditLogs(userId: $userId, limit: $limit, offset: $offset) {
    id
    action
    resource
    resourceId
    details
    createdAt
  }
}

query AuditSummary($startDate: DateTime, $endDate: DateTime) {
